package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.text.*;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Account-synced RetroAchievements library and details. */
final class RetroDataView extends ScrollView {
 private final LinearLayout body,list;private final TextView status;private final EditText search;private final Map<String,String> coverCache=new HashMap<>();private JSONArray games=new JSONArray();private JSONObject statuses=new JSONObject();private String user="";private final AccountRepository repo;
 RetroDataView(Context c){super(c);repo=new AccountRepository(c);body=new LinearLayout(c);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(16),dp(16),dp(16),dp(24));addView(body);body.addView(text("Meu Retrô",25));status=text("Sincronizando RetroAchievements…",13);body.addView(status);search=NativeSheet.input(c,"Buscar no Meu Retrô",160);body.addView(search);Spinner format=NativeSheet.options(c,new String[]{"Capas horizontais","Capas verticais"});format.setSelection(poster()?1:0);body.addView(format);format.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> parent){}public void onItemSelected(android.widget.AdapterView<?> parent,android.view.View view,int position,long id){SessionPreferences.get(c).edit().putBoolean("native_retro_poster",position==1).apply();render();}});Button add=button("＋ Adicionar do RetroAchievements");body.addView(add);add.setOnClickListener(v->catalog());Button cover=button("Alterar foto de capa");body.addView(cover);cover.setOnClickListener(v->((MainActivity)c).chooseStickerImage(uri->{status.setText("Salvando capa…");repo.uploadProfile(uri,"retro_cover",(rows,error)->{if(error!=null)status.setText(error);else load();});}));list=new LinearLayout(c);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int n,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){render();}public void afterTextChanged(Editable e){}});load();}
 private void load(){repo.retro((rows,error)->{if(error!=null){status.setText(error);return;}JSONObject data=rows.optJSONObject(0),profile=data.optJSONObject("profile"),collection=data.optJSONObject("collection");user=data.optString("usuario");games=data.optJSONArray("jogos");statuses=collection.optJSONObject("statuses");if(statuses==null)statuses=new JSONObject();status.setText(user+" · "+profile.optInt("pontos")+" pontos");android.view.View old=body.findViewWithTag("retroHero");if(old!=null)body.removeView(old);FrameLayout hero=new FrameLayout(getContext());hero.setTag("retroHero");ImageView bg=new ImageView(getContext());bg.setScaleType(ImageView.ScaleType.CENTER_CROP);hero.addView(bg,new FrameLayout.LayoutParams(-1,dp(160)));AccountImageLoader.load(bg,collection.optString("cover_url"));ImageView avatar=new ImageView(getContext());avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(dp(72),dp(72),android.view.Gravity.BOTTOM|android.view.Gravity.LEFT);lp.setMargins(dp(12),dp(12),dp(12),dp(12));hero.addView(avatar,lp);AccountImageLoader.load(avatar,profile.optString("avatar"));body.addView(hero,1,new LinearLayout.LayoutParams(-1,dp(160)));renderSummary(profile);render();});}
 private void renderSummary(JSONObject profile){android.view.View old=body.findViewWithTag("retroSummary");if(old!=null)body.removeView(old);LinearLayout summary=new LinearLayout(getContext());summary.setTag("retroSummary");summary.setOrientation(LinearLayout.VERTICAL);int earned=0,total=0,hardcore=0;for(int i=0;games!=null&&i<games.length();i++){JSONObject game=games.optJSONObject(i);if(game==null)continue;earned+=game.optInt("desbloqueadas");total+=game.optInt("total");hardcore+=game.optInt("hardcore");}String[] labels={"Pontos","True points","Jogos na coleção","Conquistas na coleção","Hardcore na coleção"};String[] values={String.valueOf(profile.optInt("pontos")),String.valueOf(profile.optInt("pontosHardcore")),String.valueOf(games==null?0:games.length()),earned+"/"+total,String.valueOf(hardcore)};for(int i=0;i<labels.length;i++){TextView tile=text(values[i]+"  ·  "+labels[i],16);tile.setPadding(dp(14),dp(12),dp(14),dp(12));tile.setBackground(AppStyle.shape(tile,NativeTheme.panelDark(getContext()),14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(6),0,0);summary.addView(tile,lp);}body.addView(summary,2);}
 private void render(){list.removeAllViews();String q=search.getText().toString().toLowerCase(Locale.ROOT);if(games==null)return;String[] keys={"progress","backlog","finished","platinum","paused","abandoned"},labels={"🎮 Em progresso","📌 Backlog","✅ Zerados","🏆 Platinados","⏸️ Pausados","❌ Abandonados"};for(int group=0;group<keys.length;group++){LinearLayout section=new LinearLayout(getContext());section.setOrientation(LinearLayout.VERTICAL);int count=0;int columns=Math.max(1,ResponsivePolicy.columns(getResources().getConfiguration().screenWidthDp-52,getResources().getConfiguration().fontScale));LinearLayout gridRow=null;for(int i=0;i<games.length();i++){JSONObject game=games.optJSONObject(i);if(game==null||!game.optString("nome").toLowerCase(Locale.ROOT).contains(q)||!retroStatus(game).equals(keys[group]))continue;count++;if((count-1)%columns==0){gridRow=new LinearLayout(getContext());section.addView(gridRow);}LinearLayout card=new LinearLayout(getContext());card.setOrientation(LinearLayout.VERTICAL);card.setPadding(0,0,0,0);ImageView cover=new ImageView(getContext());cover.setScaleType(ImageView.ScaleType.CENTER_CROP);FrameLayout art=new ArtworkFrame(getContext(),poster()?.72f:1.45f);art.addView(cover,new FrameLayout.LayoutParams(-1,-1));card.addView(art,new LinearLayout.LayoutParams(-1,-2));igdbCover(game,cover);LinearLayout info=new LinearLayout(getContext());info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(12),dp(8),dp(12),dp(12));card.addView(info);TextView gameName=text(game.optString("nome"),16);gameName.setTypeface(null,android.graphics.Typeface.BOLD);gameName.setMaxLines(2);gameName.setMinLines(2);gameName.setEllipsize(TextUtils.TruncateAt.END);info.addView(gameName);info.addView(text(statusLabel(keys[group])+" · "+game.optString("console"),13));info.addView(text(game.optInt("desbloqueadas")+"/"+game.optInt("total")+" conquistas · "+game.optInt("hardcore")+" Hardcore",13));ProgressBar progress=new ProgressBar(getContext(),null,android.R.attr.progressBarStyleHorizontal);progress.setMax(Math.max(1,game.optInt("total")));progress.setProgress(game.optInt("desbloqueadas"));info.addView(progress);card.setBackground(AppStyle.shape(card,NativeTheme.panel(getContext()),16));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(0,dp(12),(count-1)%columns==columns-1?0:dp(12),0);gridRow.addView(card,lp);card.setOnClickListener(v->details(game));}if(gridRow!=null&&count%columns!=0)for(int spacer=count%columns;spacer<columns;spacer++)gridRow.addView(new android.view.View(getContext()),new LinearLayout.LayoutParams(0,1,1));if(count>0){TextView heading=text(labels[group]+" · "+count,20);heading.setPadding(0,dp(22),0,0);list.addView(heading);list.addView(section);}}}
 private String retroStatus(JSONObject game){return RetroStatusPolicy.resolve(statuses.optString(String.valueOf(game.optInt("gameId"))),!game.optString("premio").isEmpty(),game.optInt("total"),game.optInt("desbloqueadas"));}
 private String statusLabel(String key){return RetroStatusPolicy.label(key);}
 private boolean poster(){return SessionPreferences.get(getContext()).getBoolean("native_retro_poster",true);}
 private void igdbCover(JSONObject game,ImageView image){String fallback=game.optString("capa");if(!fallback.isEmpty())AccountImageLoader.load(image,fallback);else AccountImageLoader.load(image,"");String cacheKey=game.optString("nome")+":"+game.optString("console")+":"+poster();String cached=coverCache.get(cacheKey);if(cached!=null){AccountImageLoader.load(image,cached);return;}repo.searchGames(game.optString("nome"),(rows,error)->{if(error!=null||!image.isAttachedToWindow())return;String wanted=key(game.optString("nome"));for(int i=0;i<rows.length();i++){JSONObject hit=rows.optJSONObject(i);if(hit!=null&&key(hit.optString("name")).equals(wanted)){String cover=hit.optString(poster()?"cover_image":"background_image");if(!cover.isEmpty()){coverCache.put(cacheKey,cover);AccountImageLoader.load(image,cover);}return;}}});}
 private String key(String s){return java.text.Normalizer.normalize(s,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");}
 private void details(JSONObject game){NativeSheet sheet=new NativeSheet(getContext(),game.optString("nome"));ImageView cover=new ImageView(getContext());cover.setScaleType(ImageView.ScaleType.FIT_CENTER);sheet.body.addView(cover,new LinearLayout.LayoutParams(-1,dp(240)));igdbCover(game,cover);TextView title=text(game.optString("nome"),24);title.setTypeface(null,android.graphics.Typeface.BOLD);sheet.body.addView(title);String[] statusKeys={"backlog","progress","finished","platinum","paused","abandoned"},statusNames={"📌 Backlog","🎮 Em progresso","✅ Zerado","🏆 Platinado","⏸️ Pausado","❌ Abandonado"};Spinner state=NativeSheet.options(getContext(),statusNames);int selected=Arrays.asList(statusKeys).indexOf(retroStatus(game));state.setSelection(Math.max(0,selected));sheet.body.addView(state);TextView saveState=text("",12);sheet.body.addView(saveState);state.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){boolean ready;public void onNothingSelected(android.widget.AdapterView<?> parent){}public void onItemSelected(android.widget.AdapterView<?> parent,android.view.View view,int position,long id){if(!ready){ready=true;return;}state.setEnabled(false);saveState.setText("Salvando status…");try{repo.retroRequest(new JSONObject().put("op","raSaveCollection").put("statusGameId",game.optInt("gameId")).put("status",statusKeys[position]),(saved,error)->{state.setEnabled(true);if(error!=null){saveState.setText(error);return;}try{statuses.put(String.valueOf(game.optInt("gameId")),statusKeys[position]);}catch(JSONException ignored){}saveState.setText("Status atualizado.");render();});}catch(JSONException e){state.setEnabled(true);saveState.setText("Status inválido.");}}});addDetail(sheet.body,"Plataforma",game.optString("console","Retro"));addDetail(sheet.body,"Conquistas",game.optInt("desbloqueadas")+" de "+game.optInt("total"));addDetail(sheet.body,"Progresso",game.optInt("total")>0?Math.round(game.optInt("desbloqueadas")*100f/game.optInt("total"))+"%":"—");addDetail(sheet.body,"Hardcore",String.valueOf(game.optInt("hardcore")));if(!game.optString("ultimaVez").isEmpty())addDetail(sheet.body,"Última atividade",game.optString("ultimaVez"));TextView catalog=text("Buscando descrição, gêneros e lançamento na IGDB…",13);sheet.body.addView(catalog);repo.searchGames(game.optString("nome"),(rows,error)->{if(!sheet.dialog.isShowing())return;if(error!=null){catalog.setText("Detalhes adicionais indisponíveis no momento.");return;}String wanted=key(game.optString("nome"));for(int i=0;i<rows.length();i++){JSONObject hit=rows.optJSONObject(i);if(hit!=null&&key(hit.optString("name")).equals(wanted)){repo.gameDescription(hit.optLong("igdb_id",hit.optLong("id")),(localized,translationError)->{if(!sheet.dialog.isShowing()||translationError!=null)return;JSONObject details=localized.optJSONObject(0);if(details!=null){String description=details.optString("description_raw");if(!description.isEmpty())DescriptionCredits.show(catalog,description+"\n\n"+hit.optString("released"));}});String description=hit.optString("description_raw",hit.optString("description"));String genres=hit.optJSONArray("genres")!=null?hit.optJSONArray("genres").toString():"";catalog.setText((description.isEmpty()?"Sem descrição disponível.":description)+(genres.isEmpty()?"":"\n\nGêneros: "+genres.replace("\"",""))+(hit.optString("released").isEmpty()?"":"\nLançamento: "+hit.optString("released")));return;}}catalog.setText("A IGDB não retornou detalhes adicionais para este título.");});Button igdb=button("Game data and media provided by IGDB.com");sheet.body.addView(igdb);igdb.setOnClickListener(v->open("https://www.igdb.com"));Button achievements=button("Ver conquistas");sheet.body.addView(achievements);LinearLayout content=new LinearLayout(getContext());content.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(content);achievements.setOnClickListener(v->{achievements.setEnabled(false);content.removeAllViews();content.addView(text("Carregando conquistas…",13));request("raConquistas",game.optInt("gameId"),"",0,(rows,error)->{achievements.setEnabled(true);content.removeAllViews();if(error!=null){content.addView(text(error,14));return;}JSONArray list=rows.optJSONObject(0).optJSONArray("lista");for(int i=0;list!=null&&i<list.length();i++){JSONObject a=list.optJSONObject(i);if(a==null)continue;boolean earned=a.optBoolean("got",false);ImageView icon=new ImageView(getContext());icon.setContentDescription(a.optString("nome")+(earned?" — adquirida":" — não adquirida"));if(!earned){android.graphics.ColorMatrix gray=new android.graphics.ColorMatrix();gray.setSaturation(0f);icon.setColorFilter(new android.graphics.ColorMatrixColorFilter(gray));}else icon.clearColorFilter();content.addView(icon,new LinearLayout.LayoutParams(dp(48),dp(48)));AccountImageLoader.load(icon,a.optString("icon"));TextView achievementTitle=text((earned?"✓ ":"")+a.optString("nome")+(a.optBoolean("hardcore")?" · Hardcore":""),16);achievementTitle.setTextColor(earned?NativeTheme.accent(getContext()):0xffa6a6a6);content.addView(achievementTitle);TextView description=text((earned?"Adquirida":"Não adquirida")+" · "+a.optString("desc")+" · "+a.optInt("pontos")+" pontos",13);if(!earned)description.setTextColor(0xffa6a6a6);content.addView(description);}});});Button remove=button("Remover do Meu Retrô");remove.setTextColor(0xffffa8b5);sheet.body.addView(remove);remove.setOnClickListener(v->new android.app.AlertDialog.Builder(getContext()).setTitle("Remover do Meu Retrô?").setMessage("As conquistas no RetroAchievements serão preservadas.").setNegativeButton("Cancelar",null).setPositiveButton("Remover",(dialog,which)->{remove.setEnabled(false);try{repo.retroRequest(new JSONObject().put("op","raSaveCollection").put("removeGameId",game.optInt("gameId")),(saved,error)->{if(error!=null){remove.setEnabled(true);Toast.makeText(getContext(),error,Toast.LENGTH_LONG).show();}else{sheet.dialog.dismiss();load();}});}catch(JSONException e){remove.setEnabled(true);}}).show());sheet.show();}
 private void addDetail(LinearLayout parent,String label,String value){TextView row=text(label.toUpperCase(Locale.ROOT)+"\n"+(value==null||value.trim().isEmpty()?"—":value),14);row.setPadding(dp(14),dp(10),dp(14),dp(10));row.setBackground(AppStyle.shape(row,0xff201b2b,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,0);parent.addView(row,lp);}
 private void open(String url){try{getContext().startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,android.net.Uri.parse(url)));}catch(android.content.ActivityNotFoundException e){Toast.makeText(getContext(),"Nenhum navegador disponível",Toast.LENGTH_SHORT).show();}}
 private void catalog(){NativeSheet sheet=new NativeSheet(getContext(),"Adicionar do RetroAchievements");sheet.body.addView(text("Digite o nome; a busca verificará todas as plataformas disponíveis, incluindo PlayStation 2.",13));EditText query=NativeSheet.input(getContext(),"Nome do jogo em qualquer plataforma",160);sheet.body.addView(query);Button find=button("Buscar em todas as plataformas");sheet.body.addView(find);LinearLayout results=new LinearLayout(getContext());results.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(results);find.setOnClickListener(v->{if(query.length()<2)return;find.setEnabled(false);results.removeAllViews();results.addView(text("Buscando nos catálogos…",13));request("raSearch",0,query.getText().toString(),0,(rows,error)->{find.setEnabled(true);results.removeAllViews();if(error!=null){results.addView(text(error,14));return;}JSONArray hits=rows.optJSONObject(0).optJSONArray("jogos");if(hits==null||hits.length()==0)results.addView(text("Nenhum jogo encontrado.",14));for(int i=0;hits!=null&&i<hits.length();i++){JSONObject g=hits.optJSONObject(i);LinearLayout result=new LinearLayout(getContext());result.setOrientation(LinearLayout.HORIZONTAL);result.setGravity(android.view.Gravity.CENTER_VERTICAL);ImageView picture=new ImageView(getContext());picture.setScaleType(ImageView.ScaleType.CENTER_CROP);result.addView(picture,new LinearLayout.LayoutParams(dp(poster()?80:140),dp(poster()?120:80)));Button add=button(g.optString("nome")+" · "+g.optString("console")+" · Adicionar");result.addView(add,new LinearLayout.LayoutParams(0,-2,1));results.addView(result);igdbCover(g,picture);add.setOnClickListener(w->{add.setEnabled(false);request("raSaveCollection",g.optInt("gameId"),"",0,(saved,err)->{if(err!=null){add.setEnabled(true);Toast.makeText(getContext(),err,Toast.LENGTH_LONG).show();}else{add.setText("✓ "+g.optString("nome"));load();}});});}});});sheet.show();}
 private void request(String op,int id,String query,int console,AccountRepository.Callback cb){try{JSONObject input=new JSONObject().put("op",op);if(id>0)input.put("gameId",id);if(op.equals("raConquistas"))input.put("usuario",user);if(op.equals("raSearch")){input.put("query",query);if(console>0)input.put("consoleId",console);}repo.retroRequest(input,cb);}catch(JSONException e){cb.done(null,"Pedido inválido.");}}
 private Button button(String s){Button b=new Button(getContext());b.setText(s);AppStyle.button(b,false);return b;}
 private TextView text(String s,int size){return NativeSheet.text(getContext(),s,size,0xffeee8ff);}
 private int dp(int n){return NativeSheet.dp(getContext(),n);}
}
